package com.aliothmoon.maafw.once;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.file.*;
public class RootSeriesV30WiringTest {
 private static String source(String name)throws Exception{return Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once",name)).replace("\r\n","\n");}
 @Test public void optionalDiagnosticsAreNeverInvokedNotCaughtAndIgnored()throws Exception{String r=source("CaptureSessionRuntime.java");assertFalse(r.contains(".seriesDiagnostics("));assertTrue(r.contains("clientDiagnosticsInvocation=NOT_INVOKED sfDiagnosticsInvocation=NOT_INVOKED"));assertTrue(r.contains("clientMetadata=UNOBSERVED layerMetadata=UNOBSERVED"));assertTrue(r.contains("if(seriesIntent!=null)rootSourceGate();"));}
 @Test public void strictSourceIdentityAndIndependentFrameBudgetsRemain()throws Exception{String r=source("CaptureSessionRuntime.java");assertTrue(r.contains("int limit=3;"));assertTrue(r.contains("rootPreflightMetadata.readPre("));assertTrue(r.contains("rootPreflightMetadata.readPost("));assertTrue(r.contains("seriesIntent.sourceMatches(seriesIndex,result.ready())"));assertTrue(r.contains("rootPreflightBefore.sameSource(after.ready())"));assertTrue(r.contains("RootImageSeriesScope.store(activity.getNoBackupFilesDir().toPath(),seriesIndex)"));}
 @Test public void unknownCleanupAndAuditMismatchStillBlockNext()throws Exception{String r=source("CaptureSessionRuntime.java");assertTrue(r.contains("!ReviewBingNavigation.knownClean()"));assertTrue(r.contains("rootResourcesAfterPostcheck(resources,()->rootResourcesClosed(result))"));assertTrue(r.contains("png.status()==PngImageAudit.Status.MATCH"));assertTrue(r.contains("maa.status()==MaaImageBufferAudit.Status.VERIFIED_EQUAL"));assertTrue(r.contains("maa.allOcrGeometry().nativeRows()>0"));assertTrue(r.contains("readOnlyObservation.capture==readOnlyCapture"));}
 @Test public void noActorPagePassOrInputAuthorityAdded()throws Exception{String r=source("CaptureSessionRuntime.java");assertTrue(r.contains("rootCandidate=seriesIntent==null&&"));assertTrue(r.contains("rootPreflightValid=seriesIntent==null&&"));assertTrue(r.contains("if(returnReadIntent!=null||boundedIntent!=null||seriesIntent!=null||RootFamilyDiagnosticProfile.ACTIVE)return null"));assertTrue(r.contains("MaaRecognizer.rootImageBufferSeriesAudit("));assertTrue(r.contains("ROOT_IMAGE_SERIES_V30"));}
 @Test public void uiDisclosesV30WindowAndOmittedDiagnostics()throws Exception{String u=source("RootCaptureUi.java");assertTrue(u.contains("v30：最多3帧只读序列"));assertTrue(u.contains("2026-11-12 00:30 至 01:30 UTC"));assertTrue(u.contains("client/SF诊断及UI probe本轮均未调用"));assertTrue(u.contains("每帧1次Maa OCR"));assertTrue(u.contains("零任务输入"));}
}
